import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易尚氏學 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易尚氏學 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"classics/shangshi/051.md","filePath":"classics/shangshi/051.md"}'),s={name:"classics/shangshi/051.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>陽遇陰則通。故名曰升。歸藏曰稱。牧誓稱而戈。注稱舉也。又譽人曰稱揚。升者升而上。舉者亦揚之使上。故歸藏曰稱。周易曰升。其義並同。陽上升。故元亨。元謂乾元也。大人謂二。二為三所阻格。故不曰利見大人。而曰用見。言二宜升五也。坤為憂為恤。二升五大人得位。故曰勿恤。震為南。為徵。三臨群陰。故南征吉。左傳成十六年。晉筮遇復。曰南國戚（左足）。以震為南。明夷九三曰南狩。亦以震為南。自震南象失傳。清儒皆用虞氏法。以二升五互離為南。</p><p>彖曰。柔以時升。巽而順。剛中而應。是以大亨。用見大人。勿恤。有慶也。南征吉。志行也。</p><p>二升五。故有慶。坤為志。三臨重坤。故曰志行。</p><p>象曰。地中生木。升。君子以順德。積小以高大。</p><p>巽為高為長。故為高大。坤為小為積。積小以高大者。言以坤陰柔順之德。積累以成其高大也。象卦形也。</p><p>初六。允升。大吉。</p><p>允施氏作a 。說文同。雲a 進也。晉六三雲。眾a 。即眾進也。茲曰a 升。仍前進而升也。進遇陽。故大吉。</p><h3 id="象曰。允升大吉。上合志也。" tabindex="-1">象曰。允升大吉。上合志也。 <a class="header-anchor" href="#象曰。允升大吉。上合志也。" aria-label="Permalink to “象曰。允升大吉。上合志也。”">​</a></h3><p>上謂二三。九家謂上交。非。巽伏故為志。</p><p>九二。孚乃利用禴。無咎。</p><p>二孚五。五坤為吝嗇。故曰掄。禴，夏日薄祭敢。兌為祭。巽為夏。故曰軍乃利用掄。無咎矣。</p><h3 id="象曰。九二之孚。有喜也。" tabindex="-1">象曰。九二之孚。有喜也。 <a class="header-anchor" href="#象曰。九二之孚。有喜也。" aria-label="Permalink to “象曰。九二之孚。有喜也。”">​</a></h3><p>升五故有喜。</p><p>九三。升虛邑。</p><p>馬雲虎丘也。按左傳僖二十八年。晉侯登有莘之虛。詩衛風升彼虛矣。虛者高丘。巽為高。故曰虛。坤為邑。升虛邑者。言升邑之高處也。正巽上象也。與同人九四之乘其庸。取象正同。荀爽作空虛解。後來諸家。以虛為坤象。多宗荀說。非。</p><h3 id="象曰。升虛邑。無所疑也。" tabindex="-1">象曰。升虛邑。無所疑也。 <a class="header-anchor" href="#象曰。升虛邑。無所疑也。" aria-label="Permalink to “象曰。升虛邑。無所疑也。”">​</a></h3><p>坤為迷為疑。陽遇陰。故無所疑。</p><p>六四。王用亨於歧山。吉。無咎。</p><p>震為王。兌為亨。震為陵為皈。而形上歧。故曰歧山。王用亨於歧山者。言望二升五。四得承陽。陰順陽。猶臣事君。望二升五。猶望工至歧山。而有所亨獻也。象曰順事。順承也。二若不升五。四如何得承陽哉。故望之也。此正文王服事殷之本旨。乃後儒謂文王作爻辭。不合自稱為王。若為殷王。又無至歧山之理。以爻辭為周公作。此無訟易辭皆由象生。故韓宣子不謂為易辭。而曰易象。即只以人事言。紂尚能國文王。何不可到歧山。且文王於此事數言之。服事忠誠。溢於言表。又豈必實有其事。乃謂王為文王。無理甚矣。李過西谷易說雲。若以此王為文王。則王用三驅。王假有廟。亦文王耶。駁舊說至詳盡。</p><h3 id="象曰。王用亨於歧山。順事也。" tabindex="-1">象曰。王用亨於歧山。順事也。 <a class="header-anchor" href="#象曰。王用亨於歧山。順事也。" aria-label="Permalink to “象曰。王用亨於歧山。順事也。”">​</a></h3><p>坤為順。言二升五。四得承陽。故曰順事。</p><p>六五。貞吉。升階。</p><p>貞吉。卜問吉也。坤為土為重。故有階級之象。升階言二升五也。五陽。故象曰大得志。</p><h3 id="象曰。貞吉升階。大得志也。" tabindex="-1">象曰。貞吉升階。大得志也。 <a class="header-anchor" href="#象曰。貞吉升階。大得志也。" aria-label="Permalink to “象曰。貞吉升階。大得志也。”">​</a></h3><p>坤為志。陽升五。故大得志</p><p>上六。冥升。利於不息之貞。</p><p>坤為晦冥為夜。故曰冥升。得陽應。故曰利於不息之貞。與利永貞同偕。蓋上六為同性之四五所格。不能應三。故有此象。</p><h3 id="象曰。冥升在上。消不富也" tabindex="-1">象曰。冥升在上。消不富也 <a class="header-anchor" href="#象曰。冥升在上。消不富也" aria-label="Permalink to “象曰。冥升在上。消不富也”">​</a></h3><p>坤消故不富。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
